#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <errno.h>

/* Upper bound used by the original program (0xBFA17DC6). */
#define MAX_VALUE 0xBFA17DC6ULL

/* Deterministic Miller–Rabin bases for 32‑bit integers. */
static const uint32_t bases[] = {2, 3, 5, 7, 11, 13};

/* Helper: (a * b) % mod – works for 64‑bit intermediate values. */
static uint64_t mul_mod(uint64_t a, uint64_t b, uint64_t mod)
{
    return (a * b) % mod;
}

/* Helper: (base^exp) % mod – binary exponentiation. */
static uint64_t pow_mod(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t result = 1;
    base %= mod;
    while (exp) {
        if (exp & 1)
            result = mul_mod(result, base, mod);
        base = mul_mod(base, base, mod);
        exp >>= 1;
    }
    return result;
}

/* Deterministic Miller–Rabin for 32‑bit numbers using the bases above. */
static int is_prime_uint32(uint32_t n)
{
    if (n < 2)               return 0;
    if (n % 2 == 0)          return n == 2;

    for (size_t i = 0; i < sizeof(bases)/sizeof(bases[0]); ++i) {
        uint32_t p = bases[i];
        if (n == p)          return 1;          /* n is one of the bases */
        if (n % p == 0)      return 0;          /* composite */
    }

    uint32_t d = n - 1;
    uint32_t s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }

    for (size_t i = 0; i < sizeof(bases)/sizeof(bases[0]); ++i) {
        uint64_t a = bases[i] % n;
        uint64_t x = pow_mod(a, d, n);
        if (x == 1 || x == n - 1)
            continue;
        int passed = 0;
        for (uint32_t r = 1; r < s; ++r) {
            x = mul_mod(x, x, n);
            if (x == n - 1) {
                passed = 1;
                break;
            }
        }
        if (!passed)
            return 0;
    }
    return 1;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    errno = 0;
    long long ll = strtoll(argv[1], &endptr, 10);

    if (errno != 0 || endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (ll < 0) {
        puts("NOT_PRIME");
        return 0;
    }

    uint64_t n = (uint64_t)ll;

    if (n > MAX_VALUE) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (is_prime_uint32((uint32_t)n))
        puts("PRIME");
    else
        puts("NOT_PRIME");

    return 0;
}
